gnn(){return"\u0627\u0644\u0623\u062e\u062a \u0627\u0644\u0623\u0635\u0639\u0628 \u0644\u0640Cindy: \u0636\u063a\u0637 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646\u060c \u0648\u0633\u0643\u0648\u0627\u062a \u0628\u064a\u0633\u062a\u0648\u0644\u060c \u0648\u0633\u062d\u0628 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644\u0629. \u062e\u0645\u0633 \u062c\u0648\u0644\u0627\u062a \u0647\u0646\u0627 \u0645\u0633\u062a\u0648\u0649 \u0644\u0627 \u064a\u0628\u0644\u063a\u0647 \u0645\u0639\u0638\u0645 \u0627\u0644\u0646\u0627\u0633."},
gno(){return"\u0627\u062c\u0631\u0650 \u0623\u0631\u0628\u0639\u0645\u0626\u0629 \u0645\u062a\u0631\u060c \u062b\u0645 \u062a\u0639\u0644\u0651\u0642 \u0628\u0627\u0644\u0639\u0642\u0644\u0629 \u0644\u0623\u0637\u0648\u0644 \u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639. \u0627\u0644\u0633\u062d\u0628\u0627\u062a \u0648\u062d\u062f\u0647\u0627 \u062a\u064f\u062d\u062a\u0633\u0628\u060c \u0648\u0627\u0644\u062c\u0631\u064a \u0647\u0648 \u0627\u0644\u0631\u0627\u062d\u0629."},
gnp(){return"\u0639\u0634\u0631\u0648\u0646 \u062b\u0627\u0646\u064a\u0629 \u0639\u0645\u0644\u060c \u0639\u0634\u0631 \u0631\u0627\u062d\u0629\u060c \u062b\u0645\u0627\u0646\u064a \u0645\u062c\u0645\u0648\u0639\u0627\u062a: \u0623\u0631\u0628\u0639 \u062f\u0642\u0627\u0626\u0642. \u0641\u064a 1996 \u0642\u0627\u0633 \u0639\u0627\u0644\u0645 \u0627\u0644\u0641\u064a\u0632\u064a\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u064a\u0627\u0628\u0627\u0646\u064a \u0625\u064a\u0632\u0648\u0645\u064a \u062a\u0627\u0628\u0627\u062a\u0627 \u0647\u0630\u0627 \u0627\u0644\u0646\u0638\u0627\u0645 \u0639\u0644\u0649 \u062f\u0631\u0627\u062c\u0629 \u0642\u064a\u0627\u0633 \u0627\u0644\u062c\u0647\u062f\u060c \u0648\u0628\u064a\u0651\u0646 \u0623\u0646\u0647 \u064a\u064f\u062c\u0647\u062f \u0627\u0644\u0646\u0638\u0627\u0645\u064a\u0646 \u0627\u0644\u0647\u0648\u0627\u0626\u064a \u0648\u0627\u0644\u0644\u0627\u0647\u0648\u0627\u0626\u064a \u0645\u0639\u064b\u0627. \u0627\u0644\u0628\u0646\u064a\u0629 \u0647\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0647\u0644: \u0628\u062d\u0644\u0648\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0633\u0627\u0628\u0639\u0629 \u064a\u062c\u0628 \u0623\u0644\u0627 \u064a\u0628\u0642\u0649 \u0634\u064a\u0621."},
gne(){return"\u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0630\u064a \u064a\u064f\u0646\u0647\u064a \u0646\u0641\u0633\u0647 \u0628\u0646\u0641\u0633\u0647. \u0643\u0644 \u062f\u0642\u064a\u0642\u0629 \u0639\u0644\u064a\u0643 \u0628\u064a\u0631\u0628\u064a \u0648\u0627\u062d\u062f \u0623\u0643\u062b\u0631 \u0645\u0646 \u0633\u0627\u0628\u0642\u062a\u0647\u0627\u060c \u0648\u0639\u0627\u062c\u0644\u064b\u0627 \u0623\u0648 \u0622\u062c\u0644\u064b\u0627 \u062a\u0646\u0641\u062f \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0646\u0641\u062f \u0623\u0646\u062a."},
gnh(){return"\u0648\u0627\u062d\u062f \u0648\u0639\u0634\u0631\u0648\u0646\u060c \u062e\u0645\u0633\u0629 \u0639\u0634\u0631\u060c \u062a\u0633\u0639\u0629: \u062b\u0631\u0633\u062a\u0631 \u0648\u0633\u062d\u0628 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644\u0629. \u0623\u0634\u0647\u0631 \u0637\u0631\u064a\u0642\u0629 \u0644\u062a\u0639\u0631\u0641 \u0633\u0642\u0641\u0643. \u0623\u0642\u0644 \u0645\u0646 \u062a\u0633\u0639 \u062f\u0642\u0627\u0626\u0642 \u0648\u0642\u062a \u062c\u064a\u062f\u060c \u0648\u0627\u0644\u0623\u0641\u0636\u0644 \u064a\u0646\u0632\u0644\u0648\u0646 \u062a\u062d\u062a \u0627\u0644\u062b\u0644\u0627\u062b."},
gnj(){return"\u062b\u0644\u0627\u062b \u062c\u0648\u0644\u0627\u062a \u0645\u0646 \u0627\u0644\u062c\u0631\u064a \u0648\u0627\u0644\u0623\u0631\u062c\u062d\u0629 \u0648\u0627\u0644\u0633\u062d\u0628 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644\u0629: \u0627\u0644\u0645\u0642\u064a\u0627\u0633 \u0627\u0644\u0645\u0631\u062c\u0639\u064a \u0644\u0644\u064a\u0627\u0642\u0629 \u0627\u0644\u0645\u062e\u062a\u0644\u0637\u0629. \u0636\u0628\u0637 \u0627\u0644\u0625\u064a\u0642\u0627\u0639 \u0641\u064a \u0627\u0644\u062c\u0631\u064a \u0627\u0644\u0623\u0648\u0644 \u064a\u062d\u0633\u0645 \u0643\u0644 \u0634\u064a\u0621."},
gni(){return"\u062b\u0644\u0627\u062b\u0648\u0646 \u0643\u0644\u064a\u0646 \u0622\u0646\u062f \u062c\u064a\u0631\u0643\u060c \u0644\u0627 \u0634\u064a\u0621 \u063a\u064a\u0631\u0647\u0627. \u0639\u0645\u0644 \u062e\u0627\u0644\u0635 \u0628\u0627\u0644\u0628\u0627\u0631: \u062a\u0630\u0647\u0628 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0623\u0648\u0644\u064b\u0627\u060c \u062b\u0645 \u0627\u0644\u0642\u0628\u0636\u0629\u060c \u062b\u0645 \u0627\u0644\u062e\u0637\u0629."},
gnm(){return"\u0645\u0626\u0629 \u0648\u062e\u0645\u0633\u0648\u0646 \u0631\u0645\u064a\u0629 \u0648\u0648\u0644 \u0628\u0648\u0644. \u0633\u0647\u0644 \u0627\u0644\u0648\u0635\u0641\u060c \u0642\u0627\u0633\u064d \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u0645\u0631\u0627\u0631: \u0627\u0644\u0633\u0643\u0648\u0627\u062a \u0647\u0648 \u0645\u0627 \u064a\u062e\u0630\u0644\u0643\u060c \u0644\u0627 \u0627\u0644\u0630\u0631\u0627\u0639\u0627\u0646."},
gnf(){return"\u062f\u064a\u062f\u0644\u0641\u062a \u0648\u0636\u063a\u0637 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646\u060c \u0648\u0627\u062d\u062f \u0648\u0639\u0634\u0631\u0648\u0646\u060c \u062e\u0645\u0633\u0629 \u0639\u0634\u0631\u060c \u062a\u0633\u0639\u0629. \u0633\u062d\u0628 \u062b\u0642\u064a\u0644 \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0648\u0642\u0648\u0641 \u0631\u0623\u0633\u064b\u0627 \u0639\u0644\u0649 \u0639\u0642\u0628: \u0645\u0632\u064a\u062c \u063a\u0631\u064a\u0628 \u0648\u0635\u0627\u062f\u0642 \u062c\u062f\u064b\u0627."},
gnk(){return"\u062b\u0644\u0627\u062b\u0648\u0646 \u0633\u0646\u0627\u062a\u0634 \u0639\u0644\u0649 \u0627\u0644\u0648\u0642\u062a. \u0627\u0644\u0645\u0642\u0627\u064a\u064a\u0633 \u0630\u0627\u062a \u0627\u0644\u062d\u0631\u0643\u0629 \u0627\u0644\u0648\u0627\u062d\u062f\u0629 \u0644\u0627 \u062a\u062a\u0631\u0643 \u0645\u062c\u0627\u0644\u064b\u0627 \u0644\u0644\u0627\u062e\u062a\u0628\u0627\u0621 \u0648\u0631\u0627\u0621 \u0636\u0628\u0637 \u0627\u0644\u0625\u064a\u0642\u0627\u0639."},
gnl(){return"\u062a\u062c\u062f\u064a\u0641\u060c \u062b\u0631\u0633\u062a\u0631\u060c \u0633\u062d\u0628 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644\u0629: \u062b\u0644\u0627\u062b \u0645\u062d\u0637\u0627\u062a \u0628\u0644\u0627 \u0631\u0627\u062d\u0629. \u0627\u0644\u062b\u0631\u0633\u062a\u0631 \u062e\u0641\u064a\u0641 \u0639\u0645\u062f\u064b\u0627\u060c \u0641\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0647\u0648 \u0647\u0644 \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u062c\u062f\u064a\u0641."},
gng(){return"\u062b\u0644\u0627\u062b \u062c\u0648\u0644\u0627\u062a \u0645\u0646 \u062e\u0645\u0633 \u0645\u062d\u0637\u0627\u062a\u060c \u062f\u0642\u064a\u0642\u0629 \u0644\u0643\u0644 \u0645\u0646\u0647\u0627\u060c \u0648\u0633\u064f\u0645\u0651\u064a \u0639\u0644\u0649 \u0648\u0635\u0641 \u0645\u0642\u0627\u062a\u0644 \u0644\u0645\u0627 \u064a\u0634\u0639\u0631 \u0628\u0647. \u0633\u0628\u0639 \u0639\u0634\u0631\u0629 \u062f\u0642\u064a\u0642\u0629 \u0625\u062c\u0645\u0627\u0644\u064b\u0627\u060c \u0648\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0645\u062c\u0645\u0648\u0639 \u0643\u0644 \u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0643\u0644 \u0627\u0644\u0645\u062d\u0637\u0627\u062a."},
