gvb(){return"Fitmer \u063a\u064a\u0631 \u0645\u062b\u0628\u0651\u062a \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0639\u0629"},
gkl(){return"\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062a\u0645\u0627\u0631\u064a\u0646 \u0645\u0646 \u0627\u0644\u0633\u0627\u0639\u0629"},
gv6(){return"\u0627\u0644\u0635\u0648\u062a \u0641\u064a \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0645\u0634\u062a\u0631\u0643"},
gv7(){return"\u064a\u0628\u0642\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0622\u062e\u0631 \u0635\u0627\u0645\u062a\u064b\u0627. \u0648\u0627\u0644\u0633\u0627\u0639\u0629 \u062a\u0647\u062a\u0632 \u062f\u0627\u0626\u0645\u064b\u0627."},
