gvx(){return"\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438\u0439 \u0441\u0435\u043a\u0443\u043d\u0434\u043e\u043c\u0456\u0440 \u043f\u043e\u0437\u0431\u0443\u0432\u0441\u044f \u0444\u0430\u043b\u044c\u0448\u0438\u0432\u043e\u0433\u043e \u043a\u0456\u043b\u044c\u0446\u044f \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0443 \u2014 \u0442\u0435\u043f\u0435\u0440 \u0446\u0435\u0439 \u043f\u0440\u043e\u0441\u0442\u0456\u0440 \u0437\u0430\u043f\u043e\u0432\u043d\u044e\u0454 \u043a\u043d\u043e\u043f\u043a\u0430 \u0432\u0456\u0434\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f, \u0442\u043e\u0436 \u0446\u0438\u0444\u0435\u0440\u0431\u043b\u0430\u0442 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043d\u0430\u0442\u044f\u043a\u0430\u0454 \u043d\u0430 \u0444\u0456\u043d\u0456\u0448\u043d\u0443 \u043c\u0435\u0436\u0443."},
